                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and
                                not in_panel(nr, nc) and
                                grid[nr][nc] == color and
                                (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))

    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
